  window.si_switchTab=function(tab){if(typeof SI==='undefined')return;SI.tab=tab;['siTabEquip','siTabAcc'].forEach(function(id){var el=document.getElementById(id);if(el)el.classList.toggle('active',(id==='siTabEquip')===(tab==='equip'));});['siEquipFilters','siEquipKpiGrid','siEquipSection'].forEach(function(id){var el=document.getElementById(id);if(el)el.classList.toggle('hidden',tab!=='equip');});['siAccFilters','siAccKpiGrid','siAccSection'].forEach(function(id){var el=document.getElementById(id);if(el)el.classList.toggle('hidden',tab!=='acc');});si_applyFilters();};
  window.si_renderKpi=function(){if(typeof SI==='undefined'||!SI.raw)return;var c=countStatus(SI.inv),items=[['อุปกรณ์ทั้งหมด',SI.inv.length,'fa-boxes-stacked','#2563eb','#dbeafe'],['พร้อมส่ง',c['พร้อมส่ง'],META['พร้อมส่ง'].icon,META['พร้อมส่ง'].color,META['พร้อมส่ง'].bg],['รอสอบเทียบ',c['รอสอบเทียบ'],META['รอสอบเทียบ'].icon,META['รอสอบเทียบ'].color,META['รอสอบเทียบ'].bg],['เช่ายืม',c['เช่ายืม'],META['เช่ายืม'].icon,META['เช่ายืม'].color,META['เช่ายืม'].bg],['ใช้งานไม่ได้',c['ใช้งานไม่ได้'],META['ใช้งานไม่ได้'].icon,META['ใช้งานไม่ได้'].color,META['ใช้งานไม่ได้'].bg],['ไม่พบในรายการ',c['ไม่พบในรายการ'],META['ไม่พบในรายการ'].icon,META['ไม่พบในรายการ'].color,META['ไม่พบในรายการ'].bg]];html('siEquipKpiGrid',items.map(function(i){return'<div class="sp-kpi" style="--tone:'+i[3]+'"><div class="ico" style="background:'+i[4]+'"><i class="fas '+i[2]+'" style="color:'+i[3]+'"></i></div><div class="label">'+esc(i[0])+'</div><div class="val" style="color:'+i[3]+'">'+i[1]+'</div></div>';}).join(''));var total=SI.acc.length,stock=SI.acc.reduce(function(s,a){return s+num(a.stockQty||a.qty);},0),low=SI.acc.filter(function(a){return num(a.stockQty||a.qty)<=num(a.minStockQty||a.minStock);}).length,pending=SI.acc.filter(function(a){return /PENDING/i.test(a.status||'');}).length;html('siAccKpiGrid',[['Accessories',total,'#0ea5e9'],['Total Stock',stock,'#059669'],['Low Stock',low,'#ea580c'],['Pending Approval',pending,'#7c3aed']].map(function(i){return'<div class="sp-kpi" style="--tone:'+i[2]+'"><div class="label">'+i[0]+'</div><div class="val" style="color:'+i[2]+'">'+i[1]+'</div></div>';}).join(''));};
  window.si_applyFilters=function(){if(typeof SI==='undefined')return;if((SI.tab||'equip')==='equip'){var q=val('siSearch','').toLowerCase(),b=val('siBrand','all'),m=val('siModel','all'),l=val('siLocation','all'),s=val('siStatus','all');SI.filtered=SI.inv.filter(function(d){var hay=[d.idCode,d.sn,d.brand,d.model,d.location,d.status,d.borrower,d.actionRequired].join(' ').toLowerCase();return(!q||hay.indexOf(q)>=0)&&(b==='all'||d.brand===b)&&(m==='all'||d.model===m)&&(l==='all'||d.location===l)&&(s==='all'||d.status===s);});SI.page=1;si_renderTable();}else{var aq=val('siAccSearch','').toLowerCase(),team=val('siAccTeam','all'),item=val('siAccItem','all'),st=val('siAccStatus','all'),act=val('siAccAction','all');SI.accFiltered=SI.acc.filter(function(a){var name=a.itemName||a.name||'',hay=[a.accessoryId,a.team,name,a.serialNumber||a.serial_number,a.equipmentId,a.borrower,a.status,a.actionRequired].join(' ').toLowerCase();return(!aq||hay.indexOf(aq)>=0)&&(team==='all'||a.team===team)&&(item==='all'||name===item)&&(st==='all'||a.status===st)&&(act==='all'||(a.actionRequired||a.action_required)===act);});SI.accPage=1;if(typeof old.renderAccCards==='function')old.renderAccCards();else html('siAccCards','<div class="sp-muted">No accessory renderer</div>');}};
  function actionButtons(d){var out=['<button class="csv5-action" title="Edit" onclick=\'si_editPrompt('+JSON.stringify(d).replace(/'/g,'&#39;')+')\'><i class="fas fa-pen"></i></button>'];if(d.status==='รอสอบเทียบ')out.push('<button class="csv5-action green" title="CF CAL/PM" onclick="si_runAction(\'calibrate\',\''+esc(d.idCode)+'\')"><i class="fas fa-circle-check"></i></button>');if(d.status==='พร้อมส่ง')out.push('<button class="csv5-action" title="Add to Check-Out Cart" onclick=\'si_addEquipmentToCart('+JSON.stringify(d).replace(/'/g,'&#39;')+')\'><i class="fas fa-cart-plus"></i></button>');if(d.status==='เช่ายืม'){out.push('<button class="csv5-action green" title="Return" onclick="si_returnPrompt(\''+esc(d.idCode)+'\')"><i class="fas fa-rotate-left"></i></button>');out.push('<button class="csv5-action orange" title="Extend Rental" onclick="si_extendPrompt(\''+esc(d.idCode)+'\',\''+esc(d.expectedReturn)+'\')"><i class="fas fa-calendar-plus"></i></button>');}if(['พร้อมส่ง','รอสอบเทียบ','เช่ายืม'].indexOf(d.status)>=0){out.push('<button class="csv5-action red" title="Mark Broken" onclick="si_reasonAction(\'broken\',\''+esc(d.idCode)+'\')"><i class="fas fa-screwdriver-wrench"></i></button>');out.push('<button class="csv5-action gray" title="Mark Missing" onclick="si_reasonAction(\'missing\',\''+esc(d.idCode)+'\')"><i class="fas fa-eye-slash"></i></button>');}if(d.status==='ใช้งานไม่ได้'||d.status==='ไม่พบในรายการ')out.push('<button class="csv5-action purple" title="Recover" onclick="si_runAction(\'recover\',\''+esc(d.idCode)+'\')"><i class="fas fa-heart-pulse"></i></button>');return'<div class="csv5-actions">'+out.join('')+'</div>';}
  window.si_renderTable=function(){if(typeof SI==='undefined')return;var total=SI.filtered.length,pages=Math.max(1,Math.ceil(total/SI.pageSize));SI.page=Math.max(1,Math.min(pages,SI.page));var start=(SI.page-1)*SI.pageSize,rows=SI.filtered.slice(start,start+SI.pageSize);text('siTableCount',total+' items');html('siTable',rows.length?'<div class="csv5-table-wrap"><table class="csv5-table"><thead><tr><th>#</th><th>ID Code</th><th>SN</th><th>Brand / Model</th><th>Status</th><th>Borrower</th><th>Location</th><th>Due Date</th><th>Action Required</th><th>Action</th></tr></thead><tbody>'+rows.map(function(d,i){return'<tr><td>'+(start+i+1)+'</td><td><b>'+esc(d.idCode)+'</b></td><td>'+esc(d.sn||'-')+'</td><td><b>'+esc(d.brand)+'</b><span class="sp-sub">'+esc(d.model)+'</span></td><td>'+badge(d.status)+'</td><td>'+esc(d.borrower||'-')+'</td><td>'+esc(d.location||'-')+'</td><td>'+fmtDate(d.expectedReturn) +(d.isOverdue?'<span class="csv5-contract-note">เกิน '+d.overdueDays+' วัน</span>':'')+'</td><td>'+esc(d.actionRequired||'-')+'</td><td>'+actionButtons(d)+'</td></tr>';}).join('')+'</tbody></table></div>':'<div class="sp-muted">ไม่พบข้อมูล</div>');var btns='';for(var p=Math.max(1,SI.page-2);p<=Math.min(pages,SI.page+2);p++)btns+='<button class="'+(p===SI.page?'active':'')+'" onclick="SI.page='+p+';si_renderTable()">'+p+'</button>';html('siPagination','<div class="sp-muted">Page '+SI.page+' / '+pages+' · '+total+' records</div><div class="sp-page-buttons"><button '+(SI.page<=1?'disabled':'')+' onclick="SI.page--;si_renderTable()">Prev</button>'+btns+'<button '+(SI.page>=pages?'disabled':'')+' onclick="SI.page++;si_renderTable()">Next</button></div>');};
  window.si_addEquipmentToCart=function(d){d=normalizeDevice(d);if(d.status!=='พร้อมส่ง'){if(window.Swal)Swal.fire('ไม่สามารถ Check-Out ได้','อุปกรณ์ต้องมีสถานะ พร้อมส่ง','warning');return;}if(!Array.isArray(SI.cart))SI.cart=[];if(SI.cart.some(function(x){return x.kind==='equipment'&&x.idCode===d.idCode;})){toast('info','รายการนี้อยู่ในตะกร้าแล้ว');return;}SI.cart.push(Object.assign({kind:'equipment',qty:1},d));si_updateCart();toast('success','เพิ่ม '+d.idCode+' แล้ว');};
  window.si_updateCart=function(){if(typeof SI==='undefined')return;if(!Array.isArray(SI.cart))SI.cart=[];text('siCartCount',SI.cart.length);text('siCartFabBadge',SI.cart.length);text('siCartDrawerCount',SI.cart.length);html('siCartItems',SI.cart.length?SI.cart.map(function(x,i){var isAcc=x.kind==='accessory',title=isAcc?(x.itemName||x.name):x.idCode,sub=isAcc?('Accessory · Qty '+num(x.qty||x.issueQty||1)):(x.brand+' · '+x.model+' · '+x.status),serialFields=isAcc?'':('<div class="ces-rental-accessory-sn-v266"><label>AC Plug SN<input value="'+esc(x.acPlugSn||x.ac_plug_sn||'')+'" oninput="SI.cart['+i+'].acPlugSn=this.value" placeholder="AC Plug serial"></label><label>Clamp SN<input value="'+esc(x.clampSn||x.clamp_sn||'')+'" oninput="SI.cart['+i+'].clampSn=this.value" placeholder="Clamp serial"></label></div>');return'<div class="csv5-cart-item ces-cart-rental-v266"><div style="min-width:0;flex:1"><b>'+esc(title)+'</b><small>'+esc(sub)+'</small>'+serialFields+'</div><button class="csv5-action red" onclick="SI.cart.splice('+i+',1);si_updateCart()"><i class="fas fa-times"></i></button></div>';}).join(''):'<div class="sp-muted" style="text-align:center;padding:30px">ตะกร้าว่าง</div>');var eq=SI.cart.filter(function(x){return x.kind==='equipment';}).length,acc=SI.cart.filter(function(x){return x.kind==='accessory';}).reduce(function(s,x){return s+num(x.qty||1);},0);html('siCartDetailSummary','<div class="sp-field"><div class="k">SUMMARY</div><div class="v">Equipment '+eq+' รายการ · Accessories '+acc+' ชิ้น</div></div>');};
  window.si_openCart=function(){si_updateCart();var o=document.getElementById('siCartOverlay'),d=document.getElementById('siCartDrawer');if(o)o.classList.remove('hidden');if(d)d.style.right='0';};
  window.si_closeCart=function(){var o=document.getElementById('siCartOverlay'),d=document.getElementById('siCartDrawer');if(o)o.classList.add('hidden');if(d)d.style.right='-520px';};
  window.si_toggleCart=function(){var d=document.getElementById('siCartDrawer');if(d&&d.style.right==='0px')si_closeCart();else si_openCart();};
  window.si_submitCheckout=async function(){if(!SI.cart.length){if(window.Swal)Swal.fire('ตะกร้าว่าง','','info');return;}var borrower=val('siBorrower','').trim(),location=val('siCheckoutLocation','').trim(),due=val('siDueDate',''),borrowDate=val('siBorrowDate','')||today(),note=val('siNote','');if(!borrower||!location||!due){if(window.Swal)Swal.fire('ข้อมูลไม่ครบ','กรุณากรอกผู้ยืม สถานที่ และวันคืน','warning');return;}var equipment=SI.cart.filter(function(x){return x.kind==='equipment';}),accessories=SI.cart.filter(function(x){return x.kind==='accessory';});confirmLoading('กำลังบันทึก Check-Out...');try{var messages=[];if(equipment.length){var er=await gas('cesStock_checkoutBatch',[{equipment:equipment,borrower:borrower,location:location,borrowDate:borrowDate,expectedReturnDate:due,note:note,user:userName()}]);if(!er||er.success===false)throw new Error((er&&er.message)||'Equipment checkout failed');messages.push(er.message);}if(accessories.length){var ar=await gasFirst([{fn:'si_checkoutCart',args:[{equipment:[],accessories:accessories,borrower:borrower,location:location,borrowDate:borrowDate,expectedReturnDate:due,note:note}]},{fn:'si_submitMixedCheckout',args:[{equipment:[],accessories:accessories,borrower:borrower,location:location,borrowDate:borrowDate,expectedReturnDate:due,note:note}]}]);if(ar&&ar.success===false)throw new Error(ar.message||'Accessory request failed');messages.push((ar&&ar.message)||'Accessory request submitted');}SI.cart=[];si_updateCart();si_closeCart();closeSwal();if(window.Swal)await Swal.fire('สำเร็จ',messages.join('<br>'),'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();if(window.Swal)Swal.fire('Check-Out Error',errMsg(e),'error');}};
  window.si_runAction=async function(action,idCode,payload){payload=Object.assign({idCode:idCode,user:userName()},payload||{});var map={calibrate:'cesStock_cfCalPm',recover:'cesStock_recover'};var fn=map[action];if(!fn)return;confirmLoading('กำลังบันทึก...');try{var r=await gas(fn,[payload]);closeSwal();if(!r||r.success===false)throw new Error((r&&r.message)||'Action failed');if(window.Swal)await Swal.fire('สำเร็จ',r.message,'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();if(window.Swal)Swal.fire('Stock Action Error',errMsg(e),'error');}};
  window.si_reasonAction=function(action,idCode){if(!window.Swal)return;var label=action==='broken'?'ใช้งานไม่ได้':'ไม่พบในรายการ';Swal.fire({title:label+' · '+idCode,html:'<input id="csv5Reason" class="swal2-input" placeholder="สาเหตุ / หมายเหตุ">',icon:'warning',showCancelButton:true,confirmButtonText:'ยืนยัน',preConfirm:function(){return document.getElementById('csv5Reason').value||label;}}).then(async function(x){if(!x.isConfirmed)return;confirmLoading('กำลังบันทึก...');try{var fn=action==='broken'?'cesStock_markBroken':'cesStock_markMissing';var r=await gas(fn,[{idCode:idCode,reason:x.value,note:x.value,user:userName()}]);closeSwal();if(!r||r.success===false)throw new Error((r&&r.message)||'Action failed');await Swal.fire('สำเร็จ',r.message,'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();Swal.fire('Stock Action Error',errMsg(e),'error');}});};
  window.si_returnPrompt=function(idOrDevice){var id=typeof idOrDevice==='string'?idOrDevice:(idOrDevice&&idOrDevice.idCode);if(!window.Swal)return;Swal.fire({title:'Return · '+id,html:'<input id="csv5ReturnLoc" class="swal2-input" value="Warehouse" placeholder="สถานที่รับคืน"><input id="csv5ReturnNote" class="swal2-input" placeholder="หมายเหตุ">',icon:'question',showCancelButton:true,confirmButtonText:'รับคืน'}).then(async function(x){if(!x.isConfirmed)return;confirmLoading('กำลังรับคืน...');try{var r=await gas('cesStock_return',[{idCode:id,location:document.getElementById('csv5ReturnLoc').value||'Warehouse',note:document.getElementById('csv5ReturnNote').value,user:userName()}]);closeSwal();if(!r||r.success===false)throw new Error((r&&r.message)||'Return failed');await Swal.fire('สำเร็จ',r.message,'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();Swal.fire('Return Error',errMsg(e),'error');}});};
  window.si_extendPrompt=function(id,due){if(!window.Swal)return;Swal.fire({title:'ต่อสัญญา · '+id,html:'<input id="csv5Due" class="swal2-input" type="date" value="'+esc(due||'')+'"><input id="csv5ExtendNote" class="swal2-input" placeholder="หมายเหตุ">',showCancelButton:true,confirmButtonText:'ต่อสัญญา'}).then(async function(x){if(!x.isConfirmed)return;var date=document.getElementById('csv5Due').value;if(!date){Swal.fire('กรุณาเลือกวันที่','','warning');return;}confirmLoading('กำลังต่อสัญญา...');try{var r=await gas('cesStock_extendRental',[{idCode:id,expectedReturnDate:date,note:document.getElementById('csv5ExtendNote').value,user:userName()}]);closeSwal();if(!r||r.success===false)throw new Error((r&&r.message)||'Extend failed');await Swal.fire('สำเร็จ',r.message,'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();Swal.fire('Extend Error',errMsg(e),'error');}});};
  window.si_editPrompt=function(d){d=normalizeDevice(d);if(!window.Swal)return;var statusOptions=STATUS.map(function(s){return'<option '+(s===d.status?'selected':'')+'>'+s+'</option>';}).join(''),modelOptions=['Infusomat Space','Spaceplus','Sunfusion 2'].map(function(m){return'<option '+(m===d.model?'selected':'')+'>'+m+'</option>';}).join('');Swal.fire({title:'Edit Equipment · '+d.idCode,width:760,html:'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:left"><input id="csv5EdId" class="swal2-input" value="'+esc(d.idCode)+'" placeholder="ID Code"><input id="csv5EdSn" class="swal2-input" value="'+esc(d.sn)+'" placeholder="Serial Number"><select id="csv5EdBrand" class="swal2-input"><option '+(d.brand==='B.Braun'?'selected':'')+'>B.Braun</option><option '+(d.brand==='BYOND'?'selected':'')+'>BYOND</option></select><select id="csv5EdModel" class="swal2-input">'+modelOptions+'</select><input id="csv5EdLoc" class="swal2-input" value="'+esc(d.location)+'" placeholder="Location"><select id="csv5EdStatus" class="swal2-input">'+statusOptions+'</select><input id="csv5EdAction" class="swal2-input" style="grid-column:span 2" value="'+esc(d.actionRequired)+'" placeholder="Action Required"></div>',showCancelButton:true,confirmButtonText:'Save',preConfirm:function(){return{originalIdCode:d.idCode,idCode:document.getElementById('csv5EdId').value,serialNumber:document.getElementById('csv5EdSn').value,brand:document.getElementById('csv5EdBrand').value,model:document.getElementById('csv5EdModel').value,location:document.getElementById('csv5EdLoc').value,status:document.getElementById('csv5EdStatus').value,actionRequired:document.getElementById('csv5EdAction').value,user:userName()};}}).then(async function(x){if(!x.isConfirmed)return;confirmLoading('กำลังบันทึก...');try{var r=await gas('cesStock_editEquipment',[x.value]);closeSwal();if(!r||r.success===false)throw new Error((r&&r.message)||'Edit failed');await Swal.fire('สำเร็จ',r.message,'success');initStockInventoryModule(true);if(typeof initStockDashboardModule==='function')initStockDashboardModule(true);}catch(e){closeSwal();Swal.fire('Edit Error',errMsg(e),'error');}});};
  window.si_exportCurrent=function(){if(typeof SI==='undefined')return;var rows=(SI.tab==='acc'?SI.accFiltered:SI.filtered).map(function(x){if(SI.tab==='acc')return{accessory_id:x.accessoryId||x.idCode,serial_number:x.serialNumber||x.serial_number||'',team:x.team,item_name:x.itemName||x.name,rental_equipment:x.equipmentId||'',borrower:x.borrower||'',stock_qty:(x.rentalAccessory?1:(x.stockQty||x.qty)),min_stock_qty:(x.rentalAccessory?'':(x.minStockQty||x.minStock)),status:x.status,action_required:x.actionRequired};return{id_code:x.idCode,serial_number:x.sn,brand:x.brand,model:x.model,location:x.location,status:x.status,borrower:x.borrower,due_date:x.expectedReturn,action_required:x.actionRequired};});downloadCsv(rows,(SI.tab==='acc'?'Accessories':'Equipment_Inventory')+'_'+today()+'.csv');};
  window.si_printInventory=function(){window.print();};
  if(typeof old.openInventoryHistory==='function')window.si_openInventoryHistory=old.openInventoryHistory;
  if(typeof old.openMinStockConfig==='function')window.si_openMinStockConfig=old.openMinStockConfig;
