  /* ---------------- Check Stock ---------------- */
  window.initStockCheckModule=function(force){injectStyle();ensureExclusiveStockView_('check_stock');closeStaleStockLoading_();if(typeof SC!=='undefined'){SC.mode=SC.mode||'CHECK-IN';}sc_setMode((typeof SC!=='undefined'&&SC.mode)||'CHECK-IN');var seed=CSV6.dashboard||CSV6.inventory||readClientSnapshot();if(hasUsefulStockSeed_(seed))applySharedSnapshot(seed);scheduleCheckStockAux_();if(!shouldRefresh(force,seed)&&hasUsefulStockSeed_(seed)){scheduleStockRevisionCheck_();return Promise.resolve(seed);}return refreshSharedSnapshotRetry_(!!force,{priority:'active',module:'check_stock'}).catch(function(e){closeStaleStockLoading_();console.warn('[Stock Check sync]',e);return seed||null;});};
