  window.sc_lookup=async function(){var q=val('scKeyword','').trim();if(!q){if(window.Swal)Swal.fire('กรุณากรอกรหัส','','info');return;}var mode=(typeof SC!=='undefined'&&SC.mode)||'CHECK-IN';var cached=localLookup(q).map(normalizeDevice);if(cached.length)sc_renderResult(cached,cached.length===1?'CACHE-EXACT':'CACHE-PARTIAL');else loading('scResult','กำลังค้นหา '+q+' ...');try{var r;if(mode==='CAL/PM'){r=await gasFirst([{fn:'cesStock_verifyCalibration',args:[q],timeout:12000},{fn:'cesStock_lookup',args:[q],timeout:12000}]);if(r.device)r={success:true,data:[r.device],matchType:'EXACT',calibrated:r.calibrated,canCalibrate:r.canCalibrate,message:r.message};}else{r=await gasFirst([{fn:'cesStock_lookup',args:[q],timeout:12000},{fn:'sc_lookupStockDevice',args:[q],timeout:12000}]);}if(!r||r.success===false)throw new Error((r&&r.message)||'Lookup failed');sc_renderResult((r.data||[]).map(normalizeDevice),r.matchType);sc_loadLogs();}catch(e){if(!cached.length)inlineError('scResult','Check Stock Error',e,'sc_lookup()');else toast('warning','แสดงข้อมูลจาก Cache เนื่องจาก Server ตอบช้า');}};
