    +'<div class="ces-add-pump-section"><div class="ces-add-pump-section-title"><i class="fas fa-location-dot"></i><span>Ownership & location</span></div><div class="ces-add-pump-grid">'
    +'<label><span>Team</span><select id="scAddTeam" class="swal2-select"><option value="MED">MED</option><option value="LAB">LAB</option><option value="EHS">EHS</option><option value="ENV">ENV</option><option value="TES">TES</option></select></label>'
    +'<label><span>Location</span><input id="scAddLocation" class="swal2-input" value="Warehouse"></label>'
    +'<label><span>Borrower / Customer</span><input id="scAddBorrower" class="swal2-input" placeholder="Optional"></label>'
    +'<label><span>Due Date</span><input id="scAddDue" class="swal2-input" type="date"></label>'
    +'<label class="ces-add-pump-note"><span>Note</span><textarea id="scAddNote" class="swal2-textarea" placeholder="Other details (optional)"></textarea></label></div></div></div>';
  var result=await Swal.fire({title:'Add New Infusion Pump',width:'min(1180px,97vw)',showCancelButton:true,confirmButtonText:'Save Equipment',cancelButtonText:'Cancel',customClass:{popup:'ces-add-pump-popup',confirmButton:'ces-add-pump-save'},html:html,didOpen:function(){
    var brand=document.getElementById('scAddBrand'),model=document.getElementById('scAddModel');
    function fill(){var list=brand.value==='B.Braun'?['Infusomat Space','Spaceplus']:brand.value==='BYOND'?['Sunfusion 2']:[];model.innerHTML='<option value="">Select Model</option>'+list.map(function(x){return '<option value="'+x+'">'+x+'</option>';}).join('');}
    brand.addEventListener('change',fill);fill();
  },preConfirm:function(){
    var get=function(id){var n=document.getElementById(id);return n?String(n.value||'').trim():'';};
    var v={idCode:get('scAddId'),serialNumber:get('scAddSn'),brand:get('scAddBrand'),model:get('scAddModel'),itemName:get('scAddModel'),category:'Infusion Pump',team:get('scAddTeam'),location:get('scAddLocation'),status:get('scAddStatus'),borrower:get('scAddBorrower'),dueDate:get('scAddDue'),note:get('scAddNote'),user:(window.CES_CURRENT_USER&&window.CES_CURRENT_USER.id)||''};
    if(!v.idCode||!v.serialNumber||!v.brand||!v.model){Swal.showValidationMessage('กรอก ID Code, Serial Number, Brand และ Model ให้ครบ');return false;}return v;
  }});
  if(!result.isConfirmed)return;
